vars.processors:
- dissect:
    tokenizer: "/nsm/zeek/logs/current/%{pipeline}.log"
    field: log.file.path
    trim_chars: ".log"
    target_prefix: ""
- script:
    lang: javascript
    source: |
      function process(event) {
        var pl = event.Get("pipeline");
        event.Put("@metadata.pipeline", "zeek." + pl);
        var src = (event.Get("log.file.fingerprint") || "") + "|" + (event.Get("log.offset") || "");
        var h = 5381;
        for (var i = 0; i < src.length; i++) { h = ((h << 5) + h + src.charCodeAt(i)) >>> 0; }
        event.Put("metadata._id", "nss-" + h.toString(16));
      }
- add_fields:
    target: event
    fields:
      category: network
      module: zeek
- add_tags:
    tags: ["ics"]
    when:
      regexp:
        pipeline: "^bacnet|^bsap|^cip|^cotp|^dnp3|^ecat|^enip|^modbus|^opcua|^profinet|^s7comm"
